using DrawDecks.Domain;
using Xunit;
namespace DrawDecks.Domain.Tests;
public sealed class CardSystemTests {
 static readonly CardCatalog Catalog=CardCatalog.CreateDefault();
 static SeatDefinition[] Seats()=>new[]{new SeatDefinition("p1","Player 1",SeatKind.Human),new SeatDefinition("p2","Player 2",SeatKind.Cpu)};
 static MatchState Match(ulong seed=42)=>MatchFactory.Create("test-"+seed,seed,Seats(),Catalog);
 [Fact] public void CatalogIncludesAllRequestedEffects(){var effects=Catalog.Definitions.Select(x=>x.Effect).ToHashSet();foreach(var e in new[]{CardEffect.DrawTwo,CardEffect.SkipTurn,CardEffect.ReverseOrder,CardEffect.SwapHands,CardEffect.StealCard,CardEffect.DiscardRandomCard,CardEffect.BlockDraw,CardEffect.Shield,CardEffect.Reflect,CardEffect.Negate,CardEffect.Wild,CardEffect.DeckReset,CardEffect.DoubleScore})Assert.Contains(e,effects);Assert.Equal(52,Catalog.Definitions.Count(x=>x.Kind==CardKind.Standard));}
 [Fact] public void DeckShuffleIsDeterministicAndInstancesUnique(){var ids=Catalog.Definitions.Select(x=>x.Id).ToArray();var a=DeckBuilder.Create(Catalog,ids,77);var b=DeckBuilder.Create(Catalog,ids,77);Assert.Equal(a.Select(x=>x.DefinitionId),b.Select(x=>x.DefinitionId));Assert.Equal(a.Count,a.Select(x=>x.InstanceId).Distinct().Count());}
 [Fact] public void ValidationRejectsDuplicatesAndUnknownCards(){var result=DeckBuilder.Validate(Catalog,new[]{"action-skip","action-skip","bad"});Assert.False(result.IsValid);Assert.Equal(2,result.Errors.Count);}
 [Fact] public void DrawAndDiscardMoveCards(){var s=Match();var p=s.CurrentPlayer;int count=p.Hand.Count;Assert.True(GameEngine.Draw(s,p.Id).Success);Assert.Equal(count+1,p.Hand.Count);var id=p.Hand[0].InstanceId;Assert.True(GameEngine.Discard(s,p.Id,id).Success);Assert.Contains(s.DiscardPile,c=>c.InstanceId==id);}
 [Fact] public void HandLimitAndEmptyDeckAreEnforced(){var s=Match();Assert.True(GameEngine.Draw(s,s.CurrentPlayer.Id,2).Success);Assert.Equal(ActionError.HandLimitReached,GameEngine.Draw(s,s.CurrentPlayer.Id,1).Error);var tiny=MatchFactory.Create("tiny",9,Seats(),Catalog,new Ruleset(1,2),new[]{"standard-hearts-2","standard-hearts-3"});Assert.Equal(ActionError.DeckEmpty,GameEngine.Draw(tiny,tiny.CurrentPlayer.Id).Error);}
 [Fact] public void InvalidPlayDoesNotMutateHand(){var s=Match();int n=s.CurrentPlayer.Hand.Count;Assert.Equal(ActionError.CardNotInHand,GameEngine.PlayCard(s,s.CurrentPlayer.Id,"missing").Error);Assert.Equal(n,s.CurrentPlayer.Hand.Count);}
 [Fact] public void AttackCanBeNegatedAndEventsAreSequenced(){var s=Match();var a=s.CurrentPlayer;var d=s.Players[1];a.MutableHand.Add(new CardInstance("atk",Catalog.Get("attack-steal")));d.MutableHand.Add(new CardInstance("def",Catalog.Get("defense-negate")));Assert.True(GameEngine.PlayCard(s,a.Id,"atk",d.Id).Success);Assert.NotNull(s.PendingAttack);Assert.True(GameEngine.RespondToAttack(s,d.Id,"def").Success);Assert.Null(s.PendingAttack);Assert.Equal(s.Events.Count,s.Events.Select(e=>e.Sequence).Distinct().Count());}
 [Fact] public void DrawTwoResolvesInDomain(){var s=Match();var p=s.CurrentPlayer;p.MutableHand.Add(new CardInstance("draw2",Catalog.Get("action-draw-2")));int before=p.Hand.Count;Assert.True(GameEngine.PlayCard(s,p.Id,"draw2").Success);Assert.Equal(before+1,p.Hand.Count);}
 [Fact] public void ReverseAndSwapResolveInDomain(){var s=Match();var p=s.CurrentPlayer;var other=s.Players[1];p.MutableHand.Add(new CardInstance("rev",Catalog.Get("action-reverse")));Assert.True(GameEngine.PlayCard(s,p.Id,"rev").Success);Assert.Equal("p2",s.CurrentPlayer.Id);s.CurrentPlayer.MutableHand.Add(new CardInstance("swap",Catalog.Get("action-swap")));var old=s.CurrentPlayer.Hand.Where(c=>c.InstanceId!="swap").Select(c=>c.InstanceId).ToArray();var oldOther=p.Hand.Select(c=>c.InstanceId).ToArray();Assert.True(GameEngine.PlayCard(s,s.CurrentPlayer.Id,"swap",p.Id).Success);Assert.Equal(old,p.Hand.Select(c=>c.InstanceId));Assert.Equal(oldOther,other.Hand.Select(c=>c.InstanceId));}
 [Fact] public void WildSelectsAndEnforcesSuit(){var s=Match();var p=s.CurrentPlayer;p.MutableHand.Add(new CardInstance("wild",Catalog.Get("special-wild")));Assert.True(GameEngine.PlayCard(s,p.Id,"wild",chosenSuit:Suit.Hearts).Success);Assert.Equal(Suit.Hearts,s.ActiveSuit);}
 [Fact] public void DoubleScoreDoublesNextStandardCard(){var s=Match();var p=s.CurrentPlayer;p.MutableHand.Add(new CardInstance("double",Catalog.Get("special-double")));Assert.True(GameEngine.PlayCard(s,p.Id,"double").Success);Assert.True(GameEngine.EndTurn(s,s.CurrentPlayer.Id).Success);var scoring=new CardInstance("score-card",Catalog.Get("standard-hearts-10"));p.MutableHand.Add(scoring);Assert.True(GameEngine.PlayCard(s,p.Id,scoring.InstanceId).Success);Assert.Equal(20,p.Score);}
 [Fact] public void DeckResetRecyclesDiscardPile(){var s=Match();var p=s.CurrentPlayer;int before=s.DrawPileCount;p.MutableHand.Add(new CardInstance("reset",Catalog.Get("special-reset")));Assert.True(GameEngine.PlayCard(s,p.Id,"reset").Success);Assert.Equal(before+1,s.DrawPileCount);}

 [Fact] public void SkipTurnSkipsSelectedOpponent(){var s=Match();var p=s.CurrentPlayer;p.MutableHand.Add(new CardInstance("skip",Catalog.Get("action-skip")));Assert.True(GameEngine.PlayCard(s,p.Id,"skip","p2").Success);Assert.Equal("p1",s.CurrentPlayer.Id);}
 [Fact] public void StealCardTransfersOneCardAfterUnblockedAttack(){var s=Match();var a=s.CurrentPlayer;var d=s.Players[1];a.MutableHand.Add(new CardInstance("steal",Catalog.Get("attack-steal")));int attackerBefore=a.Hand.Count;int defenderBefore=d.Hand.Count;Assert.True(GameEngine.PlayCard(s,a.Id,"steal",d.Id).Success);Assert.True(GameEngine.RespondToAttack(s,d.Id,null).Success);Assert.Equal(attackerBefore,a.Hand.Count);Assert.Equal(defenderBefore-1,d.Hand.Count);}
 [Fact] public void RandomDiscardRemovesTargetCard(){var s=Match();var a=s.CurrentPlayer;var d=s.Players[1];a.MutableHand.Add(new CardInstance("discard-random",Catalog.Get("attack-discard")));int before=d.Hand.Count;Assert.True(GameEngine.PlayCard(s,a.Id,"discard-random",d.Id).Success);Assert.True(GameEngine.RespondToAttack(s,d.Id,null).Success);Assert.Equal(before-1,d.Hand.Count);}
 [Fact] public void BlockDrawPreventsTargetsNextDraw(){var s=Match();var a=s.CurrentPlayer;var d=s.Players[1];a.MutableHand.Add(new CardInstance("block",Catalog.Get("attack-block-draw")));Assert.True(GameEngine.PlayCard(s,a.Id,"block",d.Id).Success);Assert.True(GameEngine.RespondToAttack(s,d.Id,null).Success);Assert.True(GameEngine.EndTurn(s,a.Id).Success);int hand=d.Hand.Count;Assert.True(GameEngine.Draw(s,d.Id).Success);Assert.Equal(hand,d.Hand.Count);}
 [Fact] public void ReflectRedirectsAttackToOriginalAttacker(){var s=Match();var a=s.CurrentPlayer;var d=s.Players[1];a.MutableHand.Add(new CardInstance("attack",Catalog.Get("attack-discard")));d.MutableHand.Add(new CardInstance("reflect",Catalog.Get("defense-reflect")));int aHand=a.Hand.Count;Assert.True(GameEngine.PlayCard(s,a.Id,"attack",d.Id).Success);Assert.True(GameEngine.RespondToAttack(s,d.Id,"reflect").Success);Assert.Equal(aHand-2,a.Hand.Count);}
 [Fact] public void ShieldCancelsPendingAttack(){var s=Match();var a=s.CurrentPlayer;var d=s.Players[1];a.MutableHand.Add(new CardInstance("attack",Catalog.Get("attack-steal")));d.MutableHand.Add(new CardInstance("shield",Catalog.Get("defense-shield")));Assert.True(GameEngine.PlayCard(s,a.Id,"attack",d.Id).Success);Assert.True(GameEngine.RespondToAttack(s,d.Id,"shield").Success);Assert.Null(s.PendingAttack);}

 [Fact] public void EliminationCompletesMatchAndRecordsWinner(){var s=Match();Assert.True(GameEngine.EliminatePlayer(s,s.CurrentPlayer.Id,"p2").Success);Assert.Equal(MatchStatus.Completed,s.Status);Assert.Equal("p1",s.WinnerPlayerId);Assert.Contains(s.Events,e=>e.Type=="PlayerEliminated");}
 [Fact] public void TargetScoreCompletesMatch(){var s=MatchFactory.Create("score-win",15,Seats(),Catalog,new Ruleset(5,7,4,false,1));var p=s.CurrentPlayer;var standard=p.Hand.First(x=>x.Definition.Kind==CardKind.Standard);Assert.True(GameEngine.PlayCard(s,p.Id,standard.InstanceId).Success);Assert.Equal(MatchStatus.Completed,s.Status);Assert.Equal(p.Id,s.WinnerPlayerId);}

 [Fact] public void AcceptedCommandsReplayToEquivalentFinalState(){var s=Match(9876);var p=s.CurrentPlayer;Assert.True(GameEngine.Draw(s,p.Id).Success);Assert.True(GameEngine.Discard(s,p.Id,p.Hand[0].InstanceId).Success);Assert.True(GameEngine.EndTurn(s,s.CurrentPlayer.Id).Success);Assert.True(GameEngine.Discard(s,s.CurrentPlayer.Id,s.CurrentPlayer.Hand[0].InstanceId).Success);var replay=MatchReplay.Replay(s,Catalog);Assert.True(MatchReplay.AreEquivalent(s,replay));}
 [Fact] public void DeckValidationRejectsUnavailableCards(){var unavailable=new CardDefinition("locked","Locked Card",CardKind.Special,CardEffect.Wild,isAvailable:false);var catalog=new CardCatalog("test",new[]{unavailable});Assert.False(DeckBuilder.Validate(catalog,new[]{"locked"}).IsValid);}

 [Fact] public void AttackAndDefenseCommandsReplayExactly(){MatchState? source=null;for(ulong seed=1;seed<10000&&source==null;seed++){var candidate=MatchFactory.Create("replay-attack",seed,Seats(),Catalog);if(candidate.Players[0].Hand.Any(x=>x.DefinitionId=="attack-steal")&&candidate.Players[1].Hand.Any(x=>x.DefinitionId=="defense-negate"))source=candidate;}Assert.NotNull(source);var attacker=source!.Players[0];var defender=source.Players[1];var attack=attacker.Hand.First(x=>x.DefinitionId=="attack-steal");var defense=defender.Hand.First(x=>x.DefinitionId=="defense-negate");Assert.True(GameEngine.PlayCard(source,attacker.Id,attack.InstanceId,defender.Id).Success);Assert.True(GameEngine.RespondToAttack(source,defender.Id,defense.InstanceId).Success);var replay=MatchReplay.Replay(source,Catalog);Assert.True(MatchReplay.AreEquivalent(source,replay));}
}
